// Clean stringified JSON output from LLM (removes markdown backticks if present)
const rawOutput = $input.first().json.text || $input.first().json.message.content;

let parsedData;
try {
  const cleanJson = typeof rawOutput === 'string' 
    ? rawOutput.replace(/```json|```/g, '').trim() 
    : rawOutput;
  parsedData = typeof cleanJson === 'string' ? JSON.parse(cleanJson) : cleanJson;
} catch (e) {
  parsedData = $input.first().json; // Fallback if already an object
}

return [{ json: parsedData }];

// SKU Catalog
const skus = [
  {
    "sku": "SKU-ELEC-9000",
    "product_name": "Over-Ear Wireless Headphones",
    "mandatory_standards": ["RED Directive 2014/53/EU", "RoHS Directive 2011/65/EU", "EN 62368-1:2020"],
    "max_lead_concentration_ppm": 1000
  },
  {
    "sku": "SKU-ELEC-8812",
    "product_name": "Smart Ambient LED Desk Lamp",
    "mandatory_standards": ["CE Directive 2014/30/EU", "RoHS Directive 2011/65/EU", "EN 62368-1:2020"],
    "max_lead_concentration_ppm": 1000
  },
  {
    "sku": "SKU-ELEC-9007",
    "product_name": "65W Fast USB-C Wall Charger",
    "mandatory_standards": ["CE Directive 2014/35/EU", "CE Directive 2014/30/EU", "RoHS Directive 2011/65/EU"],
    "max_lead_concentration_ppm": 1000
  },
  {
    "sku": "SKU-ELEC-9001",
    "product_name": "Pro ANC Wireless Earbuds",
    "mandatory_standards": ["RED Directive 2014/53/EU", "RoHS Directive 2011/65/EU", "EN 62368-1:2020"],
    "max_lead_concentration_ppm": 1000
  },
  {
    "sku": "SKU-ELEC-9002",
    "product_name": "Fitness Tracker Smartwatch V2",
    "mandatory_standards": ["RED Directive 2014/53/EU", "CE Directive 2014/30/EU", "RoHS Directive 2011/65/EU"],
    "max_lead_concentration_ppm": 1000
  },
  {
    "sku": "SKU-ELEC-9003",
    "product_name": "Fast-Charge Power Bank 20000mAh",
    "mandatory_standards": ["CE Directive 2014/30/EU", "RoHS Directive 2011/65/EU", "EN 62133-2:2017"],
    "max_lead_concentration_ppm": 1000
  },
  {
    "sku": "SKU-ELEC-9004",
    "product_name": "Ergonomic 27-Inch 4K USB-C Monitor",
    "mandatory_standards": ["CE Directive 2014/35/EU", "CE Directive 2014/30/EU", "RoHS Directive 2011/65/EU"],
    "max_lead_concentration_ppm": 1000
  },
  {
    "sku": "SKU-ELEC-9005",
    "product_name": "7-in-1 Aluminum USB-C Hub",
    "mandatory_standards": ["CE Directive 2014/30/EU", "RoHS Directive 2011/65/EU"],
    "max_lead_concentration_ppm": 1000
  },
  {
    "sku": "SKU-ELEC-9006",
    "product_name": "Smart Home Voice Assistant Speaker",
    "mandatory_standards": ["RED Directive 2014/53/EU", "RoHS Directive 2011/65/EU", "ErP Directive 2009/125/EC"],
    "max_lead_concentration_ppm": 1000
  }
];

const extracted = $input.first().json;

let fileName = "uploaded_certificate.pdf";
const formNode = $node["n8n Form Trigger"];

if (formNode && formNode.binary) {
  const binaryKeys = Object.keys(formNode.binary);
  if (binaryKeys.length > 0) {
    const firstBinaryField = formNode.binary[binaryKeys[0]];
    fileName = firstBinaryField.fileName || firstBinaryField.filename || fileName;
  }
}

let matchedSku = null;

// Strategy 1: Filename regex match for SKU ID (e.g. SKU-ELEC-9004)
const filenameSkuMatch = fileName.match(/SKU-[A-Z]+-\d+/i);
if (filenameSkuMatch) {
  const code = filenameSkuMatch[0].toUpperCase();
  matchedSku = skus.find(s => s.sku === code);
}

// Strategy 2: Fuzzy match extracted product_name against catalog
if (!matchedSku && extracted.product_name) {
  const pName = String(extracted.product_name).toLowerCase();
  matchedSku = skus.find(s => {
    const catName = s.product_name.toLowerCase();
    const keywords = catName.split(" ").filter(w => w.length > 3);
    return keywords.filter(kw => pName.includes(kw)).length >= 2;
  });
}

return [{
  json: {
    file_name: fileName,
    extracted: extracted,
    associated_sku: matchedSku ? matchedSku.sku : "UNMATCHED_SKU",
    sku_rules: matchedSku || null,
    sku_match_success: !!matchedSku
  }
}];

const item = $input.first().json;
const extracted = item.extracted || {};
const rules = item.sku_rules;

let status = "PASS";
let priorityScore = 10;
let issues = [];

// 1. SKU Match Check
if (!item.sku_match_success) {
  status = "FLAGGED";
  priorityScore += 70; // 10 + 70 = 80 base priority
  issues.push("CRITICAL: Automated catalog matcher could not map document to internal SKU");
}

// 2. Expiration Check (Universal)
if (extracted.expiration_date) {
  const expDate = new Date(extracted.expiration_date);
  const now = new Date("2026-08-28");
  const daysToExpiry = (expDate - now) / (1000 * 60 * 60 * 24);

  if (expDate < now) {
    status = "REJECTED";
    priorityScore += 50;
    issues.push(`CRITICAL: Certificate expired on ${extracted.expiration_date}`);
  } else if (daysToExpiry <= 30) {
    if (status !== "REJECTED") status = "FLAGGED";
    priorityScore += 25;
    issues.push(`WARNING: Certificate expires within 30 days (${extracted.expiration_date})`);
  }
}

// 3. SKU-Dependent Checks (Standards & Lead limits)
if (rules && rules.mandatory_standards) {
  rules.mandatory_standards.forEach(std => {
    const found = (extracted.standards_found || []).some(s => String(s).toLowerCase().includes(std.toLowerCase()));
    if (!found) {
      if (status !== "REJECTED") status = "FLAGGED";
      priorityScore += 35;
      issues.push(`WARNING: Missing mandatory standard ${std}`);
    }
  });

  if (extracted.tested_lead_ppm && extracted.tested_lead_ppm > rules.max_lead_concentration_ppm) {
    status = "REJECTED";
    priorityScore += 45;
    issues.push(`VIOLATION: Lead concentration (${extracted.tested_lead_ppm} ppm) exceeds threshold (${rules.max_lead_concentration_ppm} ppm)`);
  }
}

// 4. Lab Accreditation Check (Case-Insensitive Universal Check)
const labAccId = String(extracted.lab_accreditation_id || "").toUpperCase();
const issuingLab = String(extracted.issuing_lab || "").toUpperCase();

if (labAccId.includes("FAKE") || labAccId.includes("UNRECOGNIZED") || issuingLab.includes("UNRECOGNIZED")) {
  status = "REJECTED";
  priorityScore += 50;
  issues.push(`CRITICAL: Suspicious or fake laboratory accreditation detected (${extracted.lab_accreditation_id || 'Unrecognized'})`);
} else if (labAccId === "NONE" || issuingLab.includes("UNACCREDITED")) {
  if (status !== "REJECTED") status = "FLAGGED";
  priorityScore += 40;
  issues.push("WARNING: Testing conducted by unaccredited lab");
}

return [{
  json: {
    ...item,
    audit_result: {
      status: status,
      screening_priority_score: Math.min(priorityScore, 100),
      flagged_issues: issues
    }
  }
}];

