// Fetch extracted data directly from your upstream compliance/extraction node
const auditData = $('Compliance Engine & Priority Scoring').first().json;

const extracted = auditData.extracted || {};
const auditResult = auditData.audit_result || {};
const flaggedIssues = auditResult.flagged_issues || [];

const tableauRecord = {
  timestamp: new Date().toISOString(),
  file_name: auditData.file_name || "",
  associated_sku: auditData.associated_sku || "",
  product_name: extracted.product_name || "",
  certificate_id: extracted.certificate_id || "",
  supplier_name: extracted.supplier_name || "",
  issuing_lab: extracted.issuing_lab || "",
  lab_accreditation_id: extracted.lab_accreditation_id || "",
  issue_date: extracted.issue_date || "",
  expiration_date: extracted.expiration_date || "",
  tested_lead_ppm: extracted.tested_lead_ppm ?? null,
  audit_status: auditResult.status || "",
  screening_priority_score: auditResult.screening_priority_score ?? null,
  flagged_issues_count: flaggedIssues.length,
  flagged_issues_detail: flaggedIssues.join(" | ")
};

return [{ json: tableauRecord }];
